UPDATE ai_run
SET status=#{status},updated_at=#{updatedAt},version=#{version}
WHERE id=#{id} AND version=#{expectedVersion}

UPDATE ai_run_invocation
SET status='COMPLETED',output_json=#{outputJson},error_code=NULL,completed_at=#{completedAt}
WHERE run_id=#{runId} AND invocation_key=#{invocationKey} AND input_fingerprint=#{inputFingerprint} AND status='RUNNING'

UPDATE ai_run_invocation
SET status='FAILED',error_code=#{errorCode},completed_at=#{completedAt}
WHERE run_id=#{runId} AND invocation_key=#{invocationKey} AND input_fingerprint=#{inputFingerprint} AND status='RUNNING'
